// 🌲 PROCEDURAL WILDERNESS GENERATOR (Optimized)
const wildernessMapArray = (function(entities) {
    const SIZE = 100;
    let wMap = new Array(SIZE).fill(0).map(() => new Array(SIZE).fill(0));
    let protectedGrid = new Array(SIZE).fill(0).map(() => new Array(SIZE).fill(0));

    // 1. Identify Towns and Dungeons based on entity types
    const towns = entities.filter(e => e.type === 'transition');
    const dungeons = entities.filter(e => e.type === 'dungeon_gate');

    const protectArea = (ex, ey, radius = 2) => {
        for(let y = ey-radius; y <= ey+radius; y++) {
            for(let x = ex-radius; x <= ex+radius; x++) {
                if(y >=0 && y < SIZE && x >=0 && x < SIZE) protectedGrid[y][x] = 1;
            }
        }
    };

    // Protect the actual entity footprints and immediate surroundings
    entities.forEach(e => {
        if(e.type === 'transition' || e.type === 'dungeon_gate' || e.type === 'town_footprint' || e.type === 'dungeon_entrance') {
            protectArea(e.x, e.y, 3); 
        }
    });

    // 🗺️ Organic Path Carving Algorithm
    const carvePath = (x1, y1, x2, y2) => {
        let cx = x1, cy = y1;
        let failsafe = 0; // Prevent infinite loops just in case

        while ((cx !== x2 || cy !== y2) && failsafe < 2000) {
            protectArea(cx, cy, 0); // Radius 0 ensures a path exactly 1 cell wide
            failsafe++;

            let moveAxis = Math.random() < 0.5 ? 'x' : 'y';
            let dir = 1;
            let isWandering = false;

            if (moveAxis === 'x') {
                if (cx === x2) {
                    // Aligned on X. 30% chance to bow outwards (wander X)
                    if (Math.random() < 0.3) { dir = Math.random() < 0.5 ? 1 : -1; isWandering = true; }
                    else { moveAxis = 'y'; dir = y2 > cy ? 1 : -1; }
                } else {
                    dir = (x2 > cx) ? 1 : -1;
                    // 15% chance to move AWAY from target on X
                    if (Math.random() < 0.15) { dir *= -1; isWandering = true; } 
                }
            } else {
                if (cy === y2) {
                    // Aligned on Y. 30% chance to bow outwards (wander Y)
                    if (Math.random() < 0.3) { dir = Math.random() < 0.5 ? 1 : -1; isWandering = true; }
                    else { moveAxis = 'x'; dir = x2 > cx ? 1 : -1; }
                } else {
                    dir = (y2 > cy) ? 1 : -1;
                    // 15% chance to move AWAY from target on Y
                    if (Math.random() < 0.15) { dir *= -1; isWandering = true; }
                }
            }

            // Wandering steps are shorter to ensure overall progress wins out
            let steps = isWandering ? (Math.floor(Math.random() * 2) + 2) : (Math.floor(Math.random() * 4) + 3);

            for (let i = 0; i < steps; i++) {
                if (moveAxis === 'x') cx += dir;
                else cy += dir;

                // Clamp to prevent walking off the map boundaries
                cx = Math.max(1, Math.min(SIZE - 2, cx));
                cy = Math.max(1, Math.min(SIZE - 2, cy));

                protectArea(cx, cy, 0);

                // Stop immediately if we magically hit the exact target mid-stride
                if (cx === x2 && cy === y2) break;
            }
        }
        protectArea(x2, y2, 0); // Ensure final destination tile is clear
    };

    // 2. Connect Towns sequentially (Nearest Neighbor) starting from Barrowtown
    if (towns.length > 0) {
        let unvisitedTowns = [...towns];

        // Find Barrowtown to start
        let startTownIdx = unvisitedTowns.findIndex(t => t.name === 'Barrowtown');
        let currentTown = unvisitedTowns.splice(startTownIdx !== -1 ? startTownIdx : 0, 1)[0];
        let townPathSequence = [currentTown];

        while(unvisitedTowns.length > 0) {
            let nearestIdx = 0;
            let minDist = Infinity;
            for(let i = 0; i < unvisitedTowns.length; i++) {
                let dist = Math.hypot(currentTown.x - unvisitedTowns[i].x, currentTown.y - unvisitedTowns[i].y);
                if(dist < minDist) {
                    minDist = dist;
                    nearestIdx = i;
                }
            }
            currentTown = unvisitedTowns.splice(nearestIdx, 1)[0];
            townPathSequence.push(currentTown);
        }

        // Carve paths sequentially between the sorted towns
        for(let i = 0; i < townPathSequence.length - 1; i++) {
            carvePath(townPathSequence[i].x, townPathSequence[i].y, townPathSequence[i+1].x, townPathSequence[i+1].y);
        }
    }

    // 3. Connect Dungeons to their Nearest Town
    dungeons.forEach(d => {
        let nearestTown = towns[0];
        let minDist = Infinity;

        towns.forEach(t => {
            let dist = Math.hypot(d.x - t.x, d.y - t.y);
            if(dist < minDist) {
                minDist = dist;
                nearestTown = t;
            }
        });

        if (nearestTown) {
            carvePath(d.x, d.y, nearestTown.x, nearestTown.y);
        }
    });

    // 4. Generate Forest with enhanced edge density
    for(let y = 0; y < SIZE; y++) {
        for(let x = 0; x < SIZE; x++) {
            // Skip areas we've protected (Towns, Dungeons, and Paths)
            if(protectedGrid[y][x] === 1) continue;

            let distToEdge = Math.min(x, y, (SIZE - 1) - x, (SIZE - 1) - y);
            let edgeFactor = Math.max(0, 1.0 - (distToEdge / 30)); 
            let density = 0.1 + (0.8 * Math.pow(edgeFactor, 2));

            if (Math.random() < density) {
                wMap[y][x] = 1;
            }
        }
    }

    // 5. Force map boundary
    for(let i=0; i<SIZE; i++) {
        wMap[0][i] = 1; wMap[SIZE-1][i] = 1;
        wMap[i][0] = 1; wMap[i][SIZE-1] = 1;
    }

    return wMap;
})(WILDERNESS_ENTITIES);

