    {"x":8,"y":10,"wallX":8,"wallY":10,"type":"shop","shopType":"healer","name":"The Balm & Bandage","signText":"The Balm & Bandage","interior":"shop_interior_balm_bandage.webp","exterior":"shop_front_balm_bandage.webp","textX":0.5,"textY":0.154,"fontSizeMult":0.036,"fontFamily":"'Georgia', serif","textColor":"#cfcfcf","shadowColor":"#000000","shadowX":1,"shadowY":1,"highlightColor":"none","highlightX":-1,"highlightY":-1,"shopAppearance":"a grand stone building with a bright blue awning and pillared entrance","desc":"Stately stone columns frame a sturdy double wooden door, set beneath a sky-blue awning adorned with a golden crest. Vibrant flower pots and green planters flank the clean stone steps, offering a peaceful sanctuary from the cold.","welcomeMsg":"Welcome to the Balm & Bandage. Whether it's a deep cut or a lingering curse, I can fix you right up."},
    {"x":3,"y":4,"wallX":3,"wallY":4,"type":"shop","shopType":"potion_maker","name":"The Liquid Crucible","signText":"The Liquid Crucible","interior":"shop_interior_liquid_crucible.webp","exterior":"shop_front_liquid_crucible.webp","textX":0.5,"textY":0.078,"fontSizeMult":0.091,"fontFamily":"'Almendra', serif","textColor":"#8c8c8c","shadowColor":"#000000","shadowX":-1,"shadowY":-1,"highlightColor":"#d9d9d9","highlightX":1,"highlightY":1,"shopAppearance":"a cracked stone apothecary with a prominent green awning","desc":"Lush green plants and assorted clay jugs line the top of a wide awning. Through the large windows, shelves packed with glass vials, stoneware crocks, and fresh-cut herbs sit ready for brewing.","welcomeMsg":"Step lively! This shop contains the concentrated essence of a thousand ingredients. What mix can I brew for your travels?","stockMultiplier":5},
    {"x":6,"y":20,"wallX":6,"wallY":20,"type":"shop","shopType":"spell_shop","name":"Enchanted Outfitter","signText":"Enchanted Outfitter","interior":"shop_interior_enchanted_outfitter.webp","exterior":"shop_front_enchanted_outfitter.webp","textX":0.508,"textY":0.155,"fontSizeMult":0.031,"fontFamily":"'Eagle Lake', serif","textColor":"#e8d17d","shadowColor":"#000000","shadowX":1,"shadowY":1,"highlightColor":"none","highlightX":0.5,"highlightY":0.5,"shopAppearance":"a dark, elegant boutique with ornate brass pillars","desc":"An elaborate golden emblem borders a large overhead display sign. Gothic arched windows feature tiered wooden shelves stacked with mystical artifacts, runic containers, and strange arcane gear glowing faintly from within.","welcomeMsg":"Ah, a customer with a taste for the arcane. You'll find my enchantments are as durable as they are powerful.","stockMultiplier":7},
    {"x":16,"y":19,"wallX":16,"wallY":19,"type":"shop","shopType":"instrument_shop","name":"The Golden Lute","signText":"The Golden Lute","interior":"shop_interior_golden_lute.webp","exterior":"shop_front_golden_lute.webp","textX":0.506,"textY":0.208,"fontSizeMult":0.063,"fontFamily":"'Parisienne', cursive","textColor":"#221100","shadowColor":"#9ec760","shadowX":1,"shadowY":1,"highlightColor":"none","highlightX":0,"highlightY":0,"shopAppearance":"an opulent wooden music workshop with ornate golden filigree","desc":"An elegant golden medallion and elaborate carvings crown a lavish storefront. Display windows feature rows of fine wooden cases, hand-carved instruments, and polished bronze apparel, welcoming musicians out of the cold.","welcomeMsg":"Welcome to The Golden Lute. I've got strings and bronze armour that will sing just as sweet as any melody. Need a look?","stockMultiplier":12},
    {"x":14,"y":6,"wallX":14,"wallY":6,"type":"shop","shopType":"bowyer","name":"Hawkeye Range","signText":"Hawkeye Range","interior":"shop_interior_hawkeye_range.webp","exterior":"shop_front_hawkeye_range.webp","textX":0.482,"textY":0.124,"fontSizeMult":0.06,"fontFamily":"'Almendra', serif","textColor":"#65462a","shadowColor":"#150f09","shadowX":-1,"shadowY":-1,"highlightColor":"#ffdab8","highlightX":1,"highlightY":1,"shopAppearance":"an elegant wooden bowyer's workshop framed by heavy stone walls","desc":"Intricately designed arrows and elegant silver crests are beautifully displayed behind polished glass panels.","welcomeMsg":"Welcome to the Hawkeye Range. The place for finest bows and ranged equipment in Frostglen.","stockMultiplier":8},
    {"x":6,"y":1,"wallX":6,"wallY":1,"type":"shop","shopType":"general_store","name":"Oddities & Provisions","signText":"Oddities & Provisions","interior":"shop_interior_oddities_provisions.webp","exterior":"shop_front_oddities_provisions.webp","textX":0.5,"textY":0.399,"fontSizeMult":0.034,"fontFamily":"'Eagle Lake', serif","textColor":"#f2f2f2","shadowColor":"#000000","shadowX":1,"shadowY":1,"highlightColor":"none","highlightX":1,"highlightY":1,"shopAppearance":"a rustic, timber-framed general store with a prominent awning","desc":"Clay jars, earthenware pots, and wooden crates are stacked neatly outside the front windows. Warm lanterns frame a sturdy central door, casting a welcoming glow over fresh herbs potted along the stone pavement.","welcomeMsg":"From rare trinkets to plain trail rations, I've got it all. You never know what you might need until you're halfway to a dungeon.","stockMultiplier":7},
    {"x":19,"y":4,"wallX":19,"wallY":4,"type":"shop","shopType":"tavern","name":"The Griffin and the Banshee","signText":"The Griffin<BR>and the Banshee","interior":"shop_interior_griffin_banshee.webp","exterior":"shop_front_griffin_banshee.webp","textX":0.5,"textY":0.111,"fontSizeMult":0.058,"fontFamily":"'Almendra', serif","textColor":"#362f26","shadowColor":"#2e271e","shadowX":-1,"shadowY":-1,"highlightColor":"#dfbf9a","highlightX":1,"highlightY":1,"shopAppearance":"a stout stone and timber tavern adorned with mystical insignias","desc":"Large wooden barrels line the stone entryway beneath an ornate wooden header featuring carvings of a golden griffin and a cloaked banshee. Inside the window, dusty bottles and flagons sit stacked beside a thick wooden door with a circular porthole.","welcomeMsg":"Welcome to the Griffin and the Banshee! Grab a drink, rest your boots, and share your stories. If you need a rumour, I've got a fresh round of gossip waiting.","stockMultiplier":8},
    {"x":1,"y":14,"wallX":1,"wallY":14,"type":"shop","shopType":"guild_hall","name":"The Heroes' Hearth","signText":"The Heroes' Hearth","interior":"shop_interior_heroes_hearth.webp","exterior":"shop_front_heroes_hearth.webp","textX":0.5,"textY":0.29,"fontSizeMult":0.045,"fontFamily":"'Eagle Lake', serif","textColor":"#48321e","shadowColor":"#17120c","shadowX":-0.5,"shadowY":-0.5,"highlightColor":"#ffc894","highlightX":0.5,"highlightY":0.5,"shopAppearance":"a heavily fortified stone and timber lodge","desc":"A large, bronze-trimmed shield medallion sits centered within a massive wooden archway. Thick double doors are guarded by iron fixtures and flanked by wooden notice boards, banners, and heavy storage barrels resting on the cobblestone pavement.","welcomeMsg":"A hearth is a warm place for brave souls. Whether you seek to hone your blade or sign up new blood, the Hearth is open."},
    {"x":10,"y":6,"type":"message","msgType":"fragments","desc":"Fragments of an old fighter's journal.","content":"\"Kargor does not want to just fight you.\"","part":1,"of":6,"isDetected":false},
    {"x":0,"y":7,"type":"message","msgType":"fragments","desc":"Fragments of an old fighter's journal.","content":"\"He wants to end you, like he ended all who opposed him in Aethelgard.\"","part":2,"of":6,"isDetected":false},
    {"x":10,"y":18,"type":"message","msgType":"fragments","desc":"Fragments of an old fighter's journal.","content":"\"I can't believe he was my hero once. I believe he is lost to me now.\"","part":3,"of":6,"isDetected":false},
    {"x":12,"y":10,"type":"message","msgType":"fragments","desc":"Fragments of an old fighter's journal.","content":"\"He won all his fights, and the crowd loved him. But it was never enough.\"","part":4,"of":6,"isDetected":false},
    {"x":19,"y":16,"type":"message","msgType":"fragments","desc":"Fragments of an old fighter's journal.","content":"\"He now serves the her because he believes the world is too loud, too painful.\"","part":5,"of":6,"isDetected":false},
    {"x":17,"y":2,"type":"message","msgType":"fragments","desc":"Fragments of an old fighter's journal.","content":"\"He craves the finality that comes with her song.\"","part":6,"of":6,"isDetected":false},
    {"x":18,"y":8,"type":"message","msgType":"frosted note","desc":"A note frosted with ice.","content":"\"Kargor was once the Champion of the Sun. Now he is the Herald of Wrath.\"","part":1,"of":4,"isDetected":false},
    {"x":8,"y":14,"type":"message","msgType":"frosted note","desc":"A note frosted with ice.","content":"\"He stood in the blizzard for days, just listening to the howling wind.\"","part":2,"of":4,"isDetected":false},
    {"x":9,"y":0,"type":"message","msgType":"frosted note","desc":"A note frosted with ice.","content":"\"He told me the world is a discordant mess that needs to be tuned.\"","part":3,"of":4,"isDetected":false},
    {"x":3,"y":18,"type":"message","msgType":"frosted note","desc":"A note frosted with ice.","content":"\"He guards the path to Aethelgard. None may pass without proving their allegiance.\"","part":4,"of":4,"isDetected":false}
