        entities:[
    {"x":19,"y":20,"wallX":19,"wallY":20,"type":"transition","desc":"the Grand Elven gates leading to the Wildlands","targetMap":"wilderness","spawnX":45,"spawnY":75,"spawnDir":2,"gateType":"f","name":"Gate to the Wildlands"},
    {"x":0,"y":1,"wallX":0,"wallY":1,"type":"shop","shopType":"armoury","name":"The Halfling's Hammer","signText":"The Halfling's Hammer","interior":"shop_interior_halflings_hammer.webp","exterior":"shop_front_halflings_hammer.webp","textX":0.5,"textY":0.296,"fontSizeMult":0.072,"fontFamily":"'Almendra', serif","textColor":"#6b6b6b","shadowColor":"#000000","shadowX":-1,"shadowY":-1,"highlightColor":"#ffffff","highlightX":1,"highlightY":1,"shopAppearance":"a compact stone smithy with a tiled stone awning and twin exterior hearths","desc":"Twin fires blaze in stone alcoves flanking an open central entryway, casting a warm orange glow onto the pavement. Polished steel helmets and metal utensils hang from sturdy timber shelves, surrounded by heavy iron-banded barrels and smithing tools.","welcomeMsg":"Forged in the heart of the mountains, these pieces are built to last. You look like you're heading somewhere nasty - let's make sure you survive it.","stockMultiplier":4},
    {"x":8,"y":10,"wallX":8,"wallY":10,"type":"shop","shopType":"healer","name":"The Balm of Gilead","signText":"The Balm of Gilead","interior":"shop_interior_balm_of_gilead.webp","exterior":"shop_front_balm_of_gilead.webp","textX":0.5,"textY":0.238,"fontSizeMult":0.062,"fontFamily":"'Georgia', serif","textColor":"#6c635a","shadowColor":"#000000","shadowX":-1,"shadowY":-1,"highlightColor":"#ffffff","highlightX":1,"highlightY":1,"shopAppearance":"a classical marble sanctuary with grand pillars and a tiled roof","desc":"Massive stone columns support a wide stone portico topped with blooming rooftop greenery. Vibrant flower pots and creeping vines frame a clean stone staircase that climbs toward a pair of stately wood and glass entrance doors.","welcomeMsg":"We specialize in the difficult cases here. If you've been mauled, cursed, or scorched, you've arrived at the right door."},
    {"x":6,"y":12,"wallX":6,"wallY":12,"type":"shop","shopType":"potion_maker","name":"The Essence Extractor","signText":"The Essence Extractor","interior":"shop_interior_essence_extractor.webp","exterior":"shop_front_essence_extractor.webp","textX":0.5,"textY":0.157,"fontSizeMult":0.065,"fontFamily":"'Almendra', serif","textColor":"#26012d","shadowColor":"none","shadowX":-1,"shadowY":-1,"highlightColor":"none","highlightX":1,"highlightY":1,"shopAppearance":"a dark weathered timber apothecary with a tiered wooden awning","desc":"Rows of small medicine bottles and glass vials are stacked tightly across a wide overhead ledge. Large wooden barrels overflowing with fresh green herbs frame a central glass-panelled door, while interior shelves sit heavily packed with alchemical ingredients.","welcomeMsg":"I distill the very soul of nature into these vials. They aren't cheap, but when your life is on the line, you'll find them invaluable.","stockMultiplier":5},
    {"x":6,"y":20,"wallX":6,"wallY":20,"type":"shop","shopType":"spell_shop","name":"The Sorcerer's Ward","signText":"The Sorcerer's Ward","interior":"shop_interior_sorcerers_ward.webp","exterior":"shop_front_sorcerers_ward.webp","textX":0.506,"textY":0.344,"fontSizeMult":0.057,"fontFamily":"'Eagle Lake', serif","textColor":"#110014","shadowColor":"none","shadowX":-0.5,"shadowY":-0.5,"highlightColor":"#999999","highlightX":-0.5,"highlightY":-0.5,"shopAppearance":"a dark, heavy stone magic boutique","desc":"An ornate golden rune sits inside a dark stone arch above a wide timber sign. Glowing amber lanterns cast long shadows across multi-tiered window displays filled with small boxes, scrolls, and curious artifacts next to a solid wooden door with a brass door knocker.","welcomeMsg":"Knowledge is power, but it comes at a price. I have staves for the prepared and wands for the ambitious. What secrets are you hunting today?","stockMultiplier":7},
    {"x":18,"y":4,"wallX":18,"wallY":4,"type":"shop","shopType":"instrument_shop","name":"Echo & Encore","signText":"Echo & Encore","interior":"shop_interior_echo_encore.webp","exterior":"shop_front_echo_encore.webp","textX":0.506,"textY":0.234,"fontSizeMult":0.09,"fontFamily":"'Parisienne', cursive","textColor":"#d1e472","shadowColor":"#000000","shadowX":1,"shadowY":1,"highlightColor":"none","highlightX":0,"highlightY":0,"shopAppearance":"a stately stone workshop with Gothic window frames and a wooden header","desc":"Intricate, frosted-glass window panels display delicate musical markings and hanging ornaments. Small wooden ledges sit below each display window, holding meticulously crafted acoustic components next to a solid timber doorway.","welcomeMsg":"You want gear that performs as well as a maestro? I've got strings that sing and brass that resounds. Take your pick.","stockMultiplier":12},
    {"x":24,"y":8,"wallX":24,"wallY":8,"type":"shop","shopType":"bowyer","name":"Heartseeker Bows","signText":"Heartseeker Bows","interior":"shop_interior_heartseeker_bows.webp","exterior":"shop_front_heartseeker_bows.webp","textX":0.519,"textY":0.335,"fontSizeMult":0.067,"fontFamily":"'Almendra', serif","textColor":"#35281d","shadowColor":"#000000","shadowX":-1,"shadowY":-1,"highlightColor":"#dba776","highlightX":1,"highlightY":1,"shopAppearance":"a rustic stone and timber bowyer with a prominent triangular gabled roofline","desc":"A large, hand-carved wooden shield insignia crowns a thick gabled entryway. The glass double doors feature elegant golden arrow motifs, framed by wooden planter barrels holding fresh greenery and white-tipped fletching ornaments.","welcomeMsg":"I don't just sell wood and string; I sell precision. At this range, you can't afford to miss. Take a look at these beauties.","stockMultiplier":8},
    {"x":30,"y":19,"wallX":30,"wallY":19,"type":"shop","shopType":"general_store","name":"Tallow & Twine","signText":"Tallow & Twine","interior":"shop_interior_tallow_twine.webp","exterior":"shop_front_tallow_twine.webp","textX":0.493,"textY":0.215,"fontSizeMult":0.066,"fontFamily":"'Eagle Lake', serif","textColor":"#221100","shadowColor":"none","shadowX":1,"shadowY":1,"highlightColor":"#979595","highlightX":1,"highlightY":1,"shopAppearance":"a charming timber-framed general store","desc":"A heavy wooden sign hangs above an array of glowing lanterns that cast a warm light over the stone pavement. The front windows and walkways are beautifully decorated with multi-coloured flowers and potted plants sitting in rustic wooden buckets.","welcomeMsg":"Provisions? Gems? Torches? I’ve stocked this shop so you don’t have to worry about the little things when the dungeon gets dark. Need anything else?","stockMultiplier":7},
    {"x":16,"y":12,"wallX":16,"wallY":12,"type":"shop","shopType":"tavern","name":"The Tipsy Tarrasque","signText":"The Tipsy Tarrasque","interior":"shop_interior_tipsy_tarrasque.webp","exterior":"shop_front_tipsy_tarrasque.webp","textX":0.5,"textY":0.361,"fontSizeMult":0.049,"fontFamily":"'Eagle Lake', serif","textColor":"#2a1704","shadowColor":"none","shadowX":1,"shadowY":1,"highlightColor":"none","highlightX":-1,"highlightY":-1,"shopAppearance":"a cozy stone and wood tavern","desc":"A menacing wooden Tarrasque head watches over the street from a tiled rooftop awning. Below a deep red canopy, wide paned windows show rows of stacked bottles and flagons, while large ale barrels rest on the cobblestones beside the entry.","welcomeMsg":"The Tarrasque might be drunk, but I'm sober as a judge. Pull up a chair. I hear things, I see things, and I pour a drink that'll make you forget the dungeon for a while.","stockMultiplier":8},
    {"x":29,"y":0,"wallX":29,"wallY":0,"type":"shop","shopType":"guild_hall","name":"The Order of the Dawn","signText":"The Order of the Dawn","interior":"shop_interior_order_of_the_dawn.webp","exterior":"shop_front_order_of_the_dawn.webp","textX":0.512,"textY":0.199,"fontSizeMult":0.04,"fontFamily":"'Almendra', serif","textColor":"#ebebeb","shadowColor":"#000000","shadowX":0.5,"shadowY":0.5,"highlightColor":"none","highlightX":0.5,"highlightY":0.5,"shopAppearance":"a stately white marble lodge with an arched timber entryway","desc":"An ornate stone archway frames a grand wooden entrance crowned by a polished shield crest. Narrow windows flank the heavy double doors, displaying framed proclamations and pristine crystal relics above neatly trimmed green planters.","welcomeMsg":"The Order welcomes those who seek discipline. You look like you've got the spark - let's see if we can turn that spark into a flame, adventurer."},
    {"x":21,"y":12,"type":"message","msgType":"journal","desc":"A journal left by a fallen hero.","content":"\"The Seraph Barachiel guards the path to Sylvash.\"","part":1,"of":7,"isDetected":false},
    {"x":23,"y":0,"type":"message","msgType":"journal","desc":"A journal left by a fallen hero.","content":"\"A fallen angel, weeping tears of mercury, his wings blackened by ash.\"","part":2,"of":7,"isDetected":false},
    {"x":11,"y":0,"type":"message","msgType":"journal","desc":"A journal left by a fallen hero.","content":"\"Beware of his dark halo, it will blind you. I found this to my cost.\"","part":3,"of":7,"isDetected":false},
    {"x":12,"y":20,"type":"message","msgType":"journal","desc":"A journal left by a fallen hero.","content":"\"He claims the the end is inevitable.\"","part":4,"of":7,"isDetected":false},
    {"x":0,"y":17,"type":"message","msgType":"journal","desc":"A journal left by a fallen hero.","content":"\"He says she is not a monster, but a necessity for this is a broken world.\"","part":5,"of":7,"isDetected":false},
    {"x":30,"y":16,"type":"message","msgType":"journal","desc":"A journal left by a fallen hero.","content":"\"Don't believe the lie. Harmony and beauty is worth saving.","part":6,"of":7,"isDetected":false},
    {"x":3,"y":0,"type":"message","msgType":"journal","desc":"A journal left by a fallen hero.","content":"\"I wish I could still see the sun rise, I feel but its warmth one last time.\"","part":7,"of":7,"isDetected":false},
    {"x":28,"y":8,"type":"message","msgType":"scripture","desc":"A page of holy scripture.","content":"\"Barachiel fell from grace not out of pride, but out of despair.\"","part":1,"of":4,"isDetected":false},
    {"x":2,"y":8,"type":"message","msgType":"scripture","desc":"A page of holy scripture.","content":"\"He believes the Lyre-Wight's song is the only true mercy left.\"","part":2,"of":4,"isDetected":false},
    {"x":20,"y":17,"type":"message","msgType":"scripture","desc":"A page of holy scripture.","content":"\"His tears burn through stone.\"","part":3,"of":4,"isDetected":false},
    {"x":14,"y":6,"type":"message","msgType":"scripture","desc":"A page of holy scripture.","content":"\"He speaks of a city of Requiem, where all souls will find peace.\"","part":4,"of":4,"isDetected":false}
]
